import{z as B,x as n,o as E,c as d,q as r,j as t,D as e,d as l,s as A,S as i,b as s}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"全双工语音 Moshi","description":"","frontmatter":{"title":"全双工语音 Moshi","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/full-duplex-speech.md","filePath":"llm/full-duplex-speech.md","lastUpdated":1791413859000}'),p={name:"llm/full-duplex-speech.md"};function h(m,a,D,T,u,c){const o=n("Mermaid");return E(),d("div",null,[a[2]||(a[2]=r('<h1 id="全双工语音-moshi" tabindex="-1">全双工语音 Moshi <a class="header-anchor" href="#全双工语音-moshi" aria-label="Permalink to &quot;全双工语音 Moshi&quot;">​</a></h1><div class="epigraph"><p>对话不是「你说完我再说」。同时听、插话、边听边组织下一句，才是全双工。</p><footer>—— Défossez 等 Moshi: a speech-text foundation model for real-time dialogue</footer></div><p><a href="/llm/valle-tts">上一课</a>是提示到整句合成。缺口是时间上重叠的听与说：用户可能打断，模型也可能在用户说话时出声或等待。Moshi 用语音–文本基础模型加全双工编解码。后课端到端对话默认双工栈已经存在，再问要不要把文本当必经中间件。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>半双工流水线：ASR → LLM → TTS，延迟叠三跳，而且强制轮次。用户插话时 TTS 还在播，系统不知道该停。全双工要求：输入音频流与输出音频流同时活着，内部状态按帧更新。Moshi 用 Mimi 等低延迟 codec，RQ-Transformer 多流（用户声、自己的声、文本「内心独白」）对齐到同一时间格。</p><p><span class="marginnote">术语翻译：半双工就是「对讲机模式」——按住才能说、对方说完你才能说；全双工是「打电话模式」——两边随时出声、随时打断。传统 ASR→LLM→TTS 流水线天生是对讲机：它必须等 ASR 判定「你说完了」才开始想，插话自然处理不了。</span></p><p>Inner Monologue 把文本当作与语音并行的潜流，而不是先写完整句再念。</p><p><span class="marginnote">「内心独白」可以想象成一个人边说边在心里打腹稿：每一帧语音旁边都跟着一个文本 token，两者同时生成、互相校准。为什么重要：纯语音模型容易「说得流利但内容跑偏」，挂一条文本流等于给语言能力（预训练文本的全部知识）接了根线。</span></p><p><span class="marginnote">帧长（如 80 ms）决定可插话粒度。比它短的停顿无法被当作轮次边界。这与视频时间 ID 必须对齐绝对时间是同一类协议。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流式 codec → 多流 Transformer → 流式解码。训练数据要含重叠说话、打断、停顿，不能只用干净朗读。评测：端到端延迟、打断后是否停、内容是否仍连贯；不要用离线 TTS MOS 代替双工。</p>',11)),(E(),t(i,null,{default:e(()=>[A(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E7%94%A8%E6%88%B7%E9%9F%B3%E9%A2%91%E6%B5%81%22%5D%20--%3E%20MOS%5B%22%E5%A4%9A%E6%B5%81%20Transformer%22%5D%0A%20%20TXT%5B%22%E6%96%87%E6%9C%AC%E6%BD%9C%E6%B5%81%22%5D%20--%3E%20MOS%0A%20%20MOS%20--%3E%20OUT%5B%22%E6%A8%A1%E5%9E%8B%E9%9F%B3%E9%A2%91%E6%B5%81%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[l("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,"多流让「正在听的声学」与「正在说的声学」分键值，避免自己的回声被当成用户。文本潜流提供可训练的语言规划，使语音不全是声学续写。没有这条潜流，模型容易声学流畅、语义空转。",-1)),(E(),t(i,null,{default:e(()=>[A(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20HDX%5B%22%E5%8D%8A%E5%8F%8C%E5%B7%A5%3A%20%E6%97%B6%E9%97%B4%E4%B8%8A%E6%8E%92%E9%98%9F%22%5D%0A%20%20%20%20S1%5B%22%E7%94%A8%E6%88%B7%E8%AF%B4%E5%AE%8C%22%5D%20--%3E%20S2%5B%22ASR%20%E8%BD%AC%E6%96%87%E5%AD%97%22%5D%20--%3E%20S3%5B%22LLM%20%E6%83%B3%E5%AE%8C%E6%95%B4%E5%8F%A5%22%5D%20--%3E%20S4%5B%22TTS%20%E6%92%AD%E6%94%BE%22%5D%0A%20%20%20%20S4%20-.%20%22%E6%9C%9F%E9%97%B4%E7%94%A8%E6%88%B7%E6%8F%92%E8%AF%9D%20%3D%20%E6%97%A0%E4%BA%BA%E5%A4%84%E7%90%86%22%20.-%3E%20S1%0A%20%20end%0A%20%20subgraph%20FDX%5B%22%E5%85%A8%E5%8F%8C%E5%B7%A5%3A%20%E5%90%8C%E4%B8%80%E5%B8%A7%E5%86%85%E5%B9%B6%E8%A1%8C%22%5D%0A%20%20%20%20F1%5B%22%E5%B8%A7%20t%3A%20%E7%94%A8%E6%88%B7%E9%9F%B3%E9%A2%91%E8%BF%9B%22%5D%20--%3E%20F2%5B%22%E5%A4%9A%E6%B5%81%20Transformer%20%E4%B8%80%E6%AD%A5%E6%9B%B4%E6%96%B0%22%5D%0A%20%20%20%20F2%20--%3E%20F3%5B%22%E5%B8%A7%20t%3A%20%E6%A8%A1%E5%9E%8B%E9%9F%B3%E9%A2%91%E5%87%BA%20%2F%20%E5%86%B3%E5%AE%9A%E7%BB%A7%E7%BB%AD%E8%AF%B4%E6%88%96%E8%AE%A9%E4%BD%8D%22%5D%0A%20%20%20%20F3%20--%3E%20F4%5B%22%E5%B8%A7%20t%2B1%3A%20%E7%AB%8B%E5%88%BB%E5%B8%A6%E7%9D%80%E6%89%93%E6%96%AD%E7%8A%B6%E6%80%81%E7%BB%A7%E7%BB%AD%22%5D%0A%20%20end%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">「分键值」的常见误区：以为模型听到的是混在一起的单一音轨。实际上用户声和模型自己的声走不同的流、不同的注意力键，模型才知道「这句是我说的、那句话对面说的」。若混成一路，自己的 TTS 回声就会诱导模型接自己的话。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Moshi 仍是一条特定栈。下一课把「语音进语音出、文本可选」收成对话系统问题。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>全双工是同时听说与打断，不是更快的 TTS。</li><li>多流与短帧 codec 是时间协议。</li><li>文本潜流用来规划内容。</li><li>出处：Défossez 等 Moshi。</li></ul>',5))])}const _=B(p,[["render",h]]);export{S as __pageData,_ as default};
